css:
.id-card {
    width: 105mm;
    height: 148mm;
    background: white;
    border: 2px solid #00844E;
    font-family: Tahoma, Arial, sans-serif;
    position: relative;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 5mm;
}

.decorative-top {
    position: absolute;
    top: 3mm;
    left: 8mm;
    right: 8mm;
    height: 8mm;
    background: linear-gradient(90deg, transparent 0%, #00844E 20%, #00844E 80%, transparent 100%);
    opacity: 0.15;
    border-radius: 50px;
}

.decorative-top::before {
    content: '';
    position: absolute;
    top: 3mm;
    left: 5mm;
    right: 5mm;
    height: 2mm;
    background: #072B1A;
    opacity: 0.1;
    border-radius: 50px;
}

.decorative-bottom {
    position: absolute;
    bottom: 3mm;
    left: 8mm;
    right: 8mm;
    height: 6mm;
    background: linear-gradient(90deg, transparent 0%, #072B1A 30%, #072B1A 70%, transparent 100%);
    opacity: 0.12;
    border-radius: 50px;
}

.decorative-bottom::before {
    content: '';
    position: absolute;
    bottom: 2mm;
    left: 10mm;
    right: 10mm;
    height: 2mm;
    background: #00844E;
    opacity: 0.08;
    border-radius: 50px;
}

.card-header {
    text-align: center;
    padding: 8mm 2mm 4mm 2mm;
    border-bottom: 2px solid #072B1A;
    width: 100%;
    margin-bottom: 8mm;
    z-index: 2;
    position: relative;
}

.company-logo {
    width: 20mm;
    height: auto;
    margin-bottom: 3mm;
}

.card-title {
    font-size: 14px;
    font-weight: bold;
    margin: 0;
    color: #00844E;
}

.card-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8mm;
    flex-grow: 1;
    width: 100%;
    z-index: 2;
    position: relative;
}

.employee-photo {
    width: 40mm;
    height: 40mm;
    border-radius: 3mm;
    object-fit: cover;
    border: 2px solid #00844E;
    flex-shrink: 0;
    display: block;
    margin: 0 auto;
}

.employee-photo-placeholder {
    width: 40mm;
    height: 40mm;
    border-radius: 3mm;
    background: #f0f0f0;
    border: 2px solid #00844E;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto;
}

.default-avatar {
    width: 30mm;
    height: 30mm;
    opacity: 0.8;
    object-fit: cover;
    border-radius: 3mm;
}

.employee-details {
    text-align: center;
    color: #000000;
    width: 100%;
}

.employee-name {
    font-size: 16px;
    font-weight: bold;
    margin-bottom: 5mm;
    color: #072B1A;
    border-bottom: 1px solid #00844E;
    padding-bottom: 2mm;
    text-align: center;
}

.employee-id {
    font-size: 12px;
    display: flex;
    flex-direction: column;
    gap: 2mm;
    align-items: center;
    text-align: center;
}

.id-label {
    color: #072B1A;
    font-weight: bold;
}

.id-value {
    font-weight: bold;
    color: #00844E;
    background: white;
    padding: 2mm 4mm;
    border: 1px solid #00844E;
    border-radius: 3mm;
    text-align: center;
    display: inline-block;
}
